CREATE TABLE IF NOT EXISTS recipes (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT 'Dinner', prep_minutes INTEGER NOT NULL DEFAULT 0, cook_minutes INTEGER NOT NULL DEFAULT 0, servings REAL NOT NULL DEFAULT 4, ingredients TEXT NOT NULL DEFAULT '[]', steps TEXT NOT NULL DEFAULT '[]', source_url TEXT NOT NULL DEFAULT '', favorite INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_recipes_updated ON recipes(updated_at DESC);
